"""Build a SQL query to insert a RDF triple into a MVCC-PostgreSQL table.

    Argument: Name of the SQL table in which the triple will be inserted.

    Returns: A prepared SQL query that can be executed with a tuple (subject, predicate, object).
    """
def get_insert_query(table_name: str) -> str {
    return f"INSERT INTO {table_name} (subject, predicate, object, insert_t, delete_t) VALUES (%s, %s, %s, transaction_timestamp(), 'infinity'::timestamp) ON CONFLICT DO NOTHING";
}

"""
    :type cert_pattern: `bytes`
    :type actual_hostname: `bytes`

    :return: `True` if *cert_pattern* matches *actual_hostname*, else `False`.
    :rtype: `bool`
    """
def _hostname_matches(cert_pattern: Any, actual_hostname: Any) -> object {
    if (b'*' in cert_pattern) {
        (cert_head, cert_tail) = cert_pattern.split(b'.', 1);
        (actual_head, actual_tail) = actual_hostname.split(b'.', 1);
        if (cert_tail != actual_tail) {
            return False;
        }
        if actual_head.startswith(b'xn--') {
            return False;
        }
        return ((cert_head == b'*') or (cert_head == actual_head));
    } else {
        return (cert_pattern == actual_hostname);
    }
}

"""
    Removes single spaces from column names in string.
    e.g., "CONTAINER ID   NAME" -> "CONTAINERID    NAME"
    This is done so that pandas can read space-delimited files without
    separating headers with names containing spaces.
    """
def despace(line: Any) -> object {
    parts = line.split(' ');
    parts = [p if p else ' ' for p in parts];
    return ''.join(parts);
}

"""Calculate the damage done by program."""
def calculate_damage(program: Any) -> object {
    (strength, damage) = (1, 0);
    for instruction in program {
        if (instruction == 'C') {
            strength *= 2;
        } else {
            damage += strength;
        }
    }
    return damage;
}

